    baseline5sUsd: round(cur.baselineUsd, 0),
    surge: round(cur.surge, 2),
    imbalance5s: round(cur.w.imbalance, 3),
    /* +1 = taker buying (pushes the index up), -1 = taker selling. */
    direction: cur.w.imbalance >= 0 ? 1 : -1,
